"""Build an offline visual review from real product and owner-reference captures."""
from pathlib import Path
import base64, html, json, sys
product, reference, empty, error, destination = map(Path, sys.argv[1:6])
views=[]
def image(path):
    return 'data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()
def add(key,label,width,filename,derived=False,reference_name=None,notes=''):
    views.append(dict(key=key,label=label,width=width,file=filename,derived=derived,ref=reference_name,notes=notes))
for width in (1440,390):
    for key,label,route in [('login','Login','_login'),('customers','Kundenliste','_kunden'),('detail','Kundendetail','_kunden_customer-one')]:
        add(key,label,width,product/f'light-{width}-{route}.png',reference_name=reference/f'reference-{key}-{width}.png')
        add('dark-'+key,'Dark Mode · '+label,width,product/f'dark-{width}-{route}.png',True,notes='Abgeleitete Farbvariante. Im Referenzpaket ist Dark Mode ausdrücklich noch nicht visuell freigegeben.')
    for key,label,query in [('contacts','Kontaktverwaltung','contacts'),('documents','Dokumente & Statistik','finances')]:
        for theme in ('light','dark'):
            add(key if theme=='light' else 'dark-'+key,label if theme=='light' else 'Dark Mode · '+label,width,product/f'{theme}-{width}-_kunden_customer-one?tab={query}.png',True,notes='Vorhandene Fachfunktion mit den gemeinsamen Komponenten gestaltet; keine vollständige Referenz für diesen Zustand.')
    add('empty','Leere Kundenliste',width,empty/f'light-{width}-_kunden.png',True,notes='Echter Leerzustand der Anwendung mit isolierten leeren API-Testdaten.')
    add('error','Fehler beim Laden',width,error/f'light-{width}-_kunden.png',True,notes='Echter Fehlerzustand bei einer isoliert simulierten API-Antwort mit HTTP 503. Keine Produktionsabfrage.')
manifest=json.loads((reference/'measurements.json').read_text())
refmap={(v['name'],v['width']):v for v in manifest['views']}
rows={}
for view in views:
    if view['derived']:continue
    width,key=view['width'],view['key']
    evidence=json.loads((product/(f'light-{width}-'+{'login':'_login','customers':'_kunden','detail':'_kunden_customer-one'}[key]+'.json')).read_text())
    actual_selector='.auth-card h1' if key=='login' else '.page-head h1'
    ref_selector='#bm .authform h2' if key=='login' else ('#bm h2' if width==1440 else '#ba h2')
    a=next((e for e in evidence['elements'] if e['selector']==actual_selector),None)
    r=next((e for e in refmap[('reference-'+key,width)]['measured'] if e['selector']==ref_selector),None)
    if a and r:
        rows[(key,width)]=[(name,r['style'][prop],a['computed'][prop]) for name,prop in [('Schrift','font-family'),('Titelgrösse','font-size'),('Schriftgewicht','font-weight'),('Zeilenhöhe','line-height'),('Laufweite','letter-spacing'),('Titeltext','color')]]
options=''.join(f'<option value="{html.escape(v["key"])}">{html.escape(v["label"])}</option>' for v in {x['key']:x for x in views}.values())
sections=[]
for n,v in enumerate(views):
    identifier=v['key']+'-'+str(v['width'])
    note=v['notes'] or ('Identische Browserbreite. Vorschau-Schalter und äusserer Darstellungsrahmen der Referenz sind entfernt; Komponenten-CSS und Referenzdateien bleiben unverändert. Die Desktop-App-Referenz nutzt die verfügbare Arbeitsbreite. Originalbranding und Bottom-Navigation folgen dem Produktvertrag.')
    figref=f'<figure class="pane reference"><figcaption>REFERENZ · {v["width"]} PX</figcaption><img src="{image(v["ref"])}" alt="Gerenderte HTML-Referenz: {html.escape(v["label"])}"/></figure>' if v['ref'] else ''
    metrics=rows.get((v['key'],v['width']),[])
    table=''
    if metrics:
        table='<details class="measurements"><summary>Gemessene Titelwerte vergleichen</summary><table><thead><tr><th>Eigenschaft</th><th>HTML-Referenz</th><th>Produkt</th><th>Vergleich</th></tr></thead><tbody>'+''.join(f'<tr><td>{html.escape(k)}</td><td>{html.escape(r)}</td><td>{html.escape(a)}</td><td class="{"ok" if r==a else "pending"}">{"gleich" if r==a else "Abweichung"}</td></tr>' for k,r,a in metrics)+'</tbody></table></details>'
    sections.append(f'''<section class="view" data-key="{v['key']}" data-width="{v['width']}" data-derived="{str(v['derived']).lower()}" id="{identifier}" {'hidden' if n else ''}><div class="view-heading"><h2>{html.escape(v['label'])}</h2><span class="badge {'derived' if v['derived'] else ''}">{'Abgeleiteter Entwurf · keine visuelle Freigabe' if v['derived'] else 'Referenzgebundener Pilot · offene Abweichungen'}</span></div><p class="context">{html.escape(note)}</p><div class="stage"><div class="image-grid {'single' if v['derived'] else ''}">{figref}<figure class="pane actual"><figcaption>ECHTE ANWENDUNG · {v['width']} PX</figcaption><img src="{image(v['file'])}" alt="Produktansicht: {html.escape(v['label'])}"/></figure></div></div>{table}</section>''')
notes=[
('Angeglichen','Schrift & Überschriften','Inter/system-ui, 600 für Haupttitel, 27 px Desktop sowie 25/23 px Mobile; Zeilenhöhe, Laufweite und Haupttextfarbe anhand der gerenderten Referenz gemessen.'),
('Angeglichen','Login','Spaltenverhältnis, Formbreite, Startposition und Feld-/Buttonradien angepasst. Die echte Anmeldung, Codeprüfung und vorhandenen Texte bleiben erhalten.'),
('Angeglichen','Kundendossier','Finanzübersicht und offene Rechnungen im Arbeitsbereich; Kontakt rechts auf Desktop und vor den Rechnungen auf Mobile. Echte Jahres- und Forderungswerte nach Währung.'),
('Angeglichen','Suche & Tabs','Suche bei den Daten, Filter daneben, Desktop-Tabs vor der Suche. Gemeinsame Linienvariante statt gefüllter Tabs.'),
('Bewahrte Ausnahme','Originalassets & Bottom-Navigation','Textlogos und die schematische Navigation der Vorschau werden nicht übernommen. Die vorhandene mobile Bottom-Navigation bleibt unverändert.'),
('Abgeleitet','Zusätzliche Funktionen','Kontakt-Tab und auf Mobile einklappbare Zusatzdaten bewahren bestehende Funktionen. Diese Ergänzungen und Dark Mode benötigen eine eigene visuelle Abnahme.'),
('Dokumentiert','Lesbarkeit & Touch','Sekundärtexte haben höheren Kontrast; mobile Eingaben bleiben für iOS ausreichend gross. Aktive Ziele sind mindestens 44 px hoch, auch wenn die Vorschau kleinere Schalter zeigt.'),
('Offen','Finanzspalten der Kundenliste','Umsatz und offener Betrag je Kundenzeile fehlen weiterhin in der bestehenden Listenantwort. Es werden weder Werte aus einer einzelnen Seite hochgerechnet noch Platzhalterbeträge angezeigt; Kontakt-/Ortspalten bleiben vorerst erhalten.'),
('Offen','Firmenwechsel','Die echte Firma ist sichtbar und öffnet ihre Einstellungen. Ein funktionierender Firmenwechsel ist im bestehenden Zugang nicht vorhanden und wird nicht durch eine Scheinaktion ersetzt.'),
('Offen','Übrige Bereiche','Nicht in dieser Pilotvorschau gezeigte Routen sind nicht visuell abgenommen. Ihre Umsetzung und abgeleiteten Entwürfe müssen vor der abschliessenden Abnahme gesondert gezeigt werden.')]
log=''.join(f'<tr><td><span class="tag {"pending" if state=="Offen" else ""}">{html.escape(state)}</span></td><td><strong>{html.escape(title)}</strong><p>{html.escape(text)}</p></td></tr>' for state,title,text in notes)
html_doc='''<!doctype html><html lang="de-CH"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BINSO ONE · UX-Vergleich</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#213047;font:14px/1.55 system-ui,sans-serif}header{background:white;border-bottom:1px solid #e1e8f0;padding:22px max(22px,calc((100vw - 1400px)/2));}header small{color:#5d7390;letter-spacing:.1em;font-size:10px}h1{font-size:25px;margin:5px 0;font-weight:600;letter-spacing:-.5px}header p{max-width:1050px;margin:8px 0 0;color:#526780}.status{display:inline-block;color:#8a5c10;background:#fff1d9;padding:4px 10px;border-radius:6px;font-size:12px;margin-top:12px}main{max-width:1440px;margin:24px auto;padding:0 20px}.controls{position:sticky;top:0;z-index:5;display:flex;gap:16px;align-items:center;flex-wrap:wrap;background:#fff;border:1px solid #e0e7f1;padding:14px 16px;border-radius:9px;box-shadow:0 3px 15px #21304708}.controls label{display:flex;gap:9px;align-items:center;color:#526780;font-size:12px}select,button{font:inherit;min-height:36px;border:1px solid #cfdae8;background:#fff;border-radius:6px;padding:7px 10px;color:#213047}button{cursor:pointer}button[aria-pressed=true]{color:#205fb5;border-color:#91b4e5;background:#edf4ff}button:disabled{opacity:.4;cursor:default}input[type=range]{width:100px;accent-color:#2566bd}.view{margin-top:24px}.view-heading{display:flex;align-items:center;gap:16px;flex-wrap:wrap}h2{font-size:21px;font-weight:600;margin:8px 0}.badge{font-size:11px;padding:5px 9px;background:#eaf2ff;border-radius:5px;color:#285b9d}.badge.derived{color:#8a5b18;background:#fff0d8}.context{font-size:12px;color:#5a6e86;max-width:1200px;margin:8px 0 16px}.stage{overflow:auto;background:#eaf0f7;border:1px solid #dae3ee;border-radius:8px;padding:16px}.image-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:start;width:100%;position:relative}.pane{margin:0;min-width:0;background:#fff;box-shadow:0 3px 15px #1f304510}.pane figcaption{font-size:10px;letter-spacing:.1em;color:#5d7390;padding:9px 12px;border-bottom:1px solid #e7edf5;background:#fff}.pane img{display:block;width:100%;height:auto}.image-grid.single{display:block;max-width:1000px;margin:auto}.image-grid.overlay{display:block}.image-grid.overlay .actual{position:absolute;left:0;top:0;width:100%;opacity:.5}.view[data-width="390"] .image-grid{max-width:820px;margin:auto}.view[data-width="390"] .image-grid.single,.view[data-width="390"] .image-grid.overlay{max-width:390px}details{background:#fff;border:1px solid #e1e8f0;border-radius:8px;margin-top:18px;padding:14px 18px}summary{cursor:pointer;font-weight:500;color:#35649e}table{border-collapse:collapse;width:100%;font-size:12px;margin-top:12px}th,td{text-align:left;padding:12px 10px;border-bottom:1px solid #e7edf5;vertical-align:top}th{color:#61748b;font-size:11px;font-weight:500}tbody tr:last-child td{border-bottom:0}td p{margin:4px 0 0;color:#526780}.ok{color:#277247}.pending{color:#9a6516}.tag{font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:#36628e;white-space:nowrap}.tag.pending{color:#9a6516}.review-log{margin:30px 0;background:#fff;border:1px solid #e1e8f0;border-radius:8px;padding:18px 20px}.review-log h2{font-size:18px}.footnote{font-size:12px;color:#61748b;margin:25px 2px}a{color:#2566bd}button:focus-visible,select:focus-visible,summary:focus-visible{outline:2px solid #2566bd;outline-offset:3px}[hidden]{display:none!important}@media(max-width:700px){.controls{position:static}.image-grid{grid-template-columns:1fr}.stage{padding:7px}.view-heading{gap:4px}.controls label{flex-wrap:wrap}td{padding:10px 6px}}
</style><header><small>BINSO ONE · VISUELLE PRÜFUNG</small><h1>Referenz und echte Anwendung</h1><p>Login, Kundenliste und Kundendetail bei 1440 und 390 Pixeln. Die Bilder stammen aus der implementierten Anwendung mit isolierten Testdaten. Die HTML-Referenzen wurden mit demselben Browser gerendert. Vorschau-Rahmen und OS-Uhr sind für den Vergleich entfernt; die Referenzdateien bleiben unverändert.</p><span class="status">Prüfbare Pilotvorschau · keine abschliessende visuelle Abnahme</span></header><main><div class="controls"><label>Ansicht <select id="viewSelect">__BINSO_OPTIONS__</select></label><div><button id="desktop" aria-pressed="true">Desktop · 1440 px</button> <button id="mobile" aria-pressed="false">Mobile · 390 px</button></div><label>Vergleich <select id="mode"><option value="side">Nebeneinander</option><option value="overlay">Überblenden</option></select></label><label>Deckkraft <input id="opacity" type="range" min="0" max="100" value="50" aria-label="Deckkraft der Implementierung"></label></div>__BINSO_SECTIONS__<section class="review-log"><h2>Änderungen und sichtbare Abweichungen</h2><table><tbody>__BINSO_LOG__</tbody></table></section><p class="footnote">Die unterschiedlichen Namen, Beträge und Zeilenanzahlen sind Testdaten, keine übernommenen Referenzdaten. Deshalb gibt es keinen irreführenden Pixel-Prozentwert. Messwerte ergänzen die Sichtprüfung, sie ersetzen sie nicht. Code und Arbeitsstand: <a href="https://github.com/oemercam/binso_admin_azure/pull/258">PR #258</a>. Kein Merge oder Deploy dieser Vorschau.</p></main><script>
const select=document.querySelector('#viewSelect'),mode=document.querySelector('#mode'),opacity=document.querySelector('#opacity'),desktop=document.querySelector('#desktop'),mobile=document.querySelector('#mobile');let width=1440;
function show(){for(const view of document.querySelectorAll('.view')){view.hidden=!(view.dataset.key===select.value&&Number(view.dataset.width)===width);if(!view.hidden){const derived=view.dataset.derived==='true',grid=view.querySelector('.image-grid');mode.disabled=derived;opacity.disabled=derived||mode.value!=='overlay';grid.classList.toggle('overlay',!derived&&mode.value==='overlay');view.querySelector('.actual').style.opacity=!derived&&mode.value==='overlay'?opacity.value/100:1}}desktop.setAttribute('aria-pressed',String(width===1440));mobile.setAttribute('aria-pressed',String(width===390))}
select.addEventListener('change',show);mode.addEventListener('change',show);opacity.addEventListener('input',show);desktop.addEventListener('click',()=>{width=1440;show()});mobile.addEventListener('click',()=>{width=390;show()});show();
</script><noscript><style>.view[hidden]{display:block!important}</style><p>JavaScript ist ausgeschaltet. Alle Ansichten werden untereinander gezeigt.</p></noscript></html>'''
html_doc=html_doc.replace('__BINSO_OPTIONS__',options).replace('__BINSO_SECTIONS__',''.join(sections)).replace('__BINSO_LOG__',log)
destination.parent.mkdir(parents=True,exist_ok=True);destination.write_text(html_doc)
print(json.dumps({'file':str(destination.resolve()),'views':len(views),'bytes':destination.stat().st_size}))
